#!/usr/bin/env python3
"""
Builds the FoodTrack icon set: assets/img/icons.svg (SVG sprite) and assets/img/icons.js (names + labels).

Style rules (keep every icon coherent):
- 24x24 grid, 2px padding, outline stroke 1.6 with round caps/joins, colour = currentColor
- "duotone": the main body is also filled with currentColor at 18% opacity (D() parts)
- no hard-coded colours: icons follow the text colour (light/dark theme, tiles, buttons)

Usage: python3 tools/build-icons.py
"""
import json, os

def D(d):  # duotone body: soft fill + outline
    return f'<path d="{d}" fill="currentColor" fill-opacity=".18"/><path d="{d}"/>'
def P(d):  # outline only
    return f'<path d="{d}"/>'
def C(x, y, r, duo=False, fill=False):
    if fill: return f'<circle cx="{x}" cy="{y}" r="{r}" fill="currentColor" stroke="none"/>'
    if duo: return f'<circle cx="{x}" cy="{y}" r="{r}" fill="currentColor" fill-opacity=".18"/><circle cx="{x}" cy="{y}" r="{r}"/>'
    return f'<circle cx="{x}" cy="{y}" r="{r}"/>'
def dots(*pts, r=.75): return ''.join(C(x, y, r, fill=True) for x, y in pts)

