def main():
    base = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'assets', 'img')
    out = ['<svg xmlns="http://www.w3.org/2000/svg" style="display:none">',
           '<!-- FoodTrack icon set, generated by tools/build-icons.py: edit that file, not this one -->']
    meta = {}
    for folder, icons in ICONS.items():
        meta[folder] = []
        for name, (label, body) in icons.items():
            out.append(f'<symbol id="{folder}-{name}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><title>{label}</title>{body}</symbol>')
            meta[folder].append([name, label])
    out.append('</svg>')
    with open(os.path.join(base, 'icons.svg'), 'w', encoding='utf-8') as f:
        f.write('\n'.join(out) + '\n')
    with open(os.path.join(base, 'icons.js'), 'w', encoding='utf-8') as f:
        f.write('/* FoodTrack icon names and Italian labels, generated by tools/build-icons.py */\n')
        f.write('window.FT_ICONS = ' + json.dumps(meta, ensure_ascii=False) + ';\n')
    # Preview page (only for development, not linked anywhere)
    cells = ''.join(f'<figure><svg><use href="icons.svg#{fo}-{n}"/></svg><figcaption>{fo}/{n}</figcaption></figure>' for fo, ic in ICONS.items() for n in ic)
    with open(os.path.join(base, '..', '..', 'tools', 'icons-preview.html'), 'w', encoding='utf-8') as f:
        f.write(f'<!doctype html><meta charset=utf-8><base href="../assets/img/"><style>body{{font:12px system-ui;display:flex;flex-wrap:wrap;gap:8px;padding:12px;color:#0A3A10;background:#fff}}figure{{margin:0;width:104px;text-align:center}}svg{{width:56px;height:56px;padding:10px;background:#C8EBC5;border-radius:16px}}</style>{cells}')
    print(sum(len(v) for v in ICONS.values()), 'icons')

if __name__ == '__main__':
    main()
